// If rows came from Google Sheets (columns: keyword, audience, tone) use them; otherwise use 3 neutral sample keywords.
const rows = $input.all().filter(i => i.json && i.json.keyword);
if (rows.length) {
  return rows.map(i => ({ json: { keyword: String(i.json.keyword).trim(), audience: i.json.audience || 'general readers', tone: i.json.tone || 'clear, friendly' } }));
}
return [
  { json: { keyword: 'standing desks 2026', audience: 'home office workers', tone: 'practical, friendly' } },
  { json: { keyword: 'how to clean a laptop keyboard', audience: 'students', tone: 'simple, step by step' } },
  { json: { keyword: 'best budget noise cancelling headphones', audience: 'commuters', tone: 'honest, comparison style' } },
];

// Build one LLM request per keyword
const cfg = $('Config').first().json;
return $input.all().map(i => {
  const k = i.json;
  const system = 'You are an SEO content writer. Write clear, helpful, original articles. No fake statistics, no made-up product claims.';
  const user = `Write a ${cfg.words}-word article for the keyword "${k.keyword}".\nAudience: ${k.audience}. Tone: ${k.tone}.\nStructure: one H1 title, a 2-sentence intro, 4 H2 sections with short paragraphs and one bullet list, a short conclusion.\nOutput Markdown only.`;
  return { json: { ...k, mode: cfg.mode, request: { model: cfg.model, temperature: 0.7, messages: [ { role: 'system', content: system }, { role: 'user', content: user } ] } } };
});

// Normalise the LLM HTTP response (OpenAI-compatible: OpenAI, DeepSeek, Moonshot, LiteLLM...)
return $input.all().map((i, idx) => {
  const src = $('Build Prompt').all()[idx].json;
  const md = i.json?.choices?.[0]?.message?.content || '';
  return { json: { keyword: src.keyword, audience: src.audience, tone: src.tone, mode: src.mode, article_md: md, llm_source: 'live' } };
});

