// Clean + format: Markdown -> clean HTML, extract title/slug/meta, quality checks
function esc(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function inline(s){return esc(s).replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*(.+?)\*/g,'<em>$1</em>');}
function mdToHtml(md){
  const lines = md.replace(/```[a-z]*\n?/gi,'').split(/\r?\n/);
  let html='', list=false;
  for (const raw of lines){
    const l = raw.trim();
    if (/^[-*] /.test(l)){ if(!list){html+='<ul>';list=true;} html+='<li>'+inline(l.slice(2))+'</li>'; continue; }
    if (list){html+='</ul>';list=false;}
    if (!l) continue;
    if (/^### /.test(l)) html+='<h3>'+inline(l.slice(4))+'</h3>';
    else if (/^## /.test(l)) html+='<h2>'+inline(l.slice(3))+'</h2>';
    else if (/^# /.test(l)) html+='<h1>'+inline(l.slice(2))+'</h1>';
    else html+='<p>'+inline(l)+'</p>';
  }
  if (list) html+='</ul>';
  return html;
}
return $input.all().map(i => {
  const md = (i.json.article_md || '').trim();
  const title = (md.match(/^#\s+(.+)$/m) || [,i.json.keyword])[1].trim();
  const html = mdToHtml(md);
  const plain = html.replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();
  const words = plain.split(' ').filter(Boolean).length;
  const slug = i.json.keyword.toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');
  const h2 = (html.match(/<h2>/g)||[]).length;
  const checks = { has_title: !!title, h2_sections: h2, enough_words: words >= 120, no_markdown_left: !/(^|\n)#+\s|\*\*/.test(plain) };
  const ok = checks.has_title && h2 >= 3 && checks.enough_words && checks.no_markdown_left;
  return { json: { keyword: i.json.keyword, title, slug, meta_description: plain.slice(0,155), word_count: words, html, status: ok ? 'READY' : 'NEEDS REVIEW', checks, llm_source: i.json.llm_source } };
});
